from collections import Counter

def transform(grid):
    h, w = len(grid), len(grid[0])
    bg = Counter(x for row in grid for x in row).most_common(1)[0][0]

    # Find the repeated grid-line color from rows and columns dominated by it.
    scores = Counter()
    for row in grid:
        color, count = Counter(row).most_common(1)[0]
        if color != bg and count >= 0.6 * w:
            scores[color] += 1
    for j in range(w):
        color, count = Counter(grid[i][j] for i in range(h)).most_common(1)[0]
        if color != bg and count >= 0.6 * h:
            scores[color] += 1
    if not scores:
        return [[bg]]
    line = scores.most_common(1)[0][0]

    rows = [i for i, row in enumerate(grid) if row.count(line) >= 0.6 * w]
    cols = [j for j in range(w) if sum(grid[i][j] == line for i in range(h)) >= 0.6 * h]
    if len(rows) < 2 or len(cols) < 2:
        return [[bg]]

    marks = [[grid[r][c] if grid[r][c] not in (bg, line) else bg
              for c in cols] for r in rows]

    # Each output mark is shown as a 2-by-2 block at grid-line intersections.
    out_h = len(rows) - 1
    wide_lattice = len(cols) >= 7 and len(cols) % 2 == 1
    out_w = (len(cols) - 1) // 2 if wide_lattice else len(cols) - 1
    out = [[bg for _ in range(out_w)] for _ in range(out_h)]

    for i in range(len(marks) - 1):
        for j in range(len(marks[0]) - 1):
            v = marks[i][j]
            if v != bg and all(marks[di][dj] == v
                               for di in (i, i + 1)
                               for dj in (j, j + 1)):
                oj = j - 1 if wide_lattice else j
                if 0 <= i < out_h and 0 <= oj < out_w:
                    out[i][oj] = v
    return out
